typedef unsigned char u_char;
typedef unsigned short u_short;
typedef unsigned int u_int;
typedef unsigned long u_long;
typedef unsigned long long u_long128;

struct sceGifPacket {
    u_int *pCurrent;
};

#define SCE_DMA_ID_CNT 1
#define SCE_DMA_ID_REF 3
#define SCE_GIF_IMAGE 2
#define SCE_GS_BITBLTBUF 0x50
#define SCE_GS_TRXREG 0x52
#define SCE_GS_TRXDIR 0x53

#define SCE_DMA_SET_TAG(qwc,pce,id,irq,addr,spr) \
    (((u_long)(qwc)) \
     | (((u_long)(pce)) << 26) \
     | (((u_long)(id)) << 28) \
     | (((u_long)(irq)) << 31) \
     | (((u_long)(u_int)(addr)) << 32) \
     | (((u_long)(spr)) << 63))

#define SCE_GIF_SET_TAG(nloop,eop,pre,prim,flg,nreg) \
    (((u_long)(nloop)) \
     | (((u_long)(eop)) << 15) \
     | (((u_long)(pre)) << 46) \
     | (((u_long)(prim)) << 47) \
     | (((u_long)(flg)) << 58) \
     | (((u_long)(nreg)) << 60))

#define SCE_GS_SET_BITBLTBUF(sbp,sbw,spsm,dbp,dbw,dpsm) \
    (((u_long)(sbp)) \
     | (((u_long)(sbw)) << 16) \
     | (((u_long)(spsm)) << 24) \
     | (((u_long)(dbp)) << 32) \
     | (((u_long)(dbw)) << 48) \
     | (((u_long)(dpsm)) << 56))

#define SCE_GS_SET_TRXREG(rrw,rrh) \
    (((u_long)(rrw)) | (((u_long)(rrh)) << 32))

#define SCE_GS_SET_TRXDIR(xdir) ((u_long)(xdir))

void nglGifPkRefLoadImage( sceGifPacket *pPacket, u_short bp, u_char psm, u_short bw, u_long128 *image, u_int size, u_int w, u_int h )
{
  u_long* Packet = (u_long*)pPacket->pCurrent;

  *(Packet++) = SCE_DMA_SET_TAG( 5, 0, SCE_DMA_ID_CNT, 0, 0, 0 );
  *(Packet++) = 0;

  *(Packet++) = SCE_GIF_SET_TAG( 3, 0, 0, 0, 0, 1 );
  *(Packet++) = 0xE;

  *(Packet++) = SCE_GS_SET_BITBLTBUF( 0, 0, 0, bp, bw, psm );
  *(Packet++) = SCE_GS_BITBLTBUF;

  *(Packet++) = SCE_GS_SET_TRXREG( w, h );
  *(Packet++) = SCE_GS_TRXREG;

  *(Packet++) = SCE_GS_SET_TRXDIR( 0 );
  *(Packet++) = SCE_GS_TRXDIR;

  *(Packet++) = SCE_GIF_SET_TAG( size, 0, 0, 0, SCE_GIF_IMAGE, 0 );
  *(Packet++) = 0;

  *(Packet++) = SCE_DMA_SET_TAG( size, 0, SCE_DMA_ID_REF, 0, image, 0 );
  *(Packet++) = 0;

  pPacket->pCurrent = (u_int*)Packet;
}
